import { Tabs as BaseTabs } from '@base-ui/react/tabs';
import { CircleAlert, MousePointer2, X } from 'lucide-react';
import { useId, useRef, type ComponentProps, type CSSProperties, type ReactNode } from 'react';
import { cn } from '../lib/cn';
import { useControllable } from '../lib/use-controllable';
import { Badge, Kbd } from './badge';
import { portTypeName, pluralRu } from './canvas-check';
import type { CanvasPortType } from './canvas-types';

/* ---------- Shell ---------- */

export type InspectorTab = 'params' | 'data' | 'runs';

export type CanvasInspectorVariant = 'panel' | 'card';

export interface CanvasInspectorProps extends Omit<ComponentProps<'section'>, 'title'> {
  /** Step name: «Новое сообщение». */
  title: string;
  /** Kind, service and number: «Триггер · Telegram · шаг 1». */
  subtitle?: ReactNode;
  /** InspectorIcon of the step kind. */
  icon?: ReactNode;
  /** Shows ×; Esc in the editor does the same. */
  onClose?: () => void;
  /** panel — fills the inspector zone of CanvasEditor (288, separator and scroll come from the zone) · card — floating 312, r16 with a shadow. */
  variant?: CanvasInspectorVariant;
  /** Errors of this step that block publishing: a danger banner above the fields. */
  errors?: number;
  /** Fields of the step, top to bottom in the order people think about them. With it the inspector has tabs. */
  params?: ReactNode;
  /** Input and output of the last run. */
  data?: ReactNode;
  /** Runs of the step. */
  runs?: ReactNode;
  /** In the tab name: «Запуски 128», 0 — «Запусков нет». */
  runCount?: number;
  tab?: InspectorTab;
  defaultTab?: InspectorTab;
  onTabChange?: (tab: InspectorTab) => void;
}

const variants: Record<CanvasInspectorVariant, string> = {
  panel: 'w-full flex-1 bg-surface-1',
  card: 'w-[312px] max-w-full overflow-hidden rounded-lg bg-surface-1 shadow-raised',
};

const tabClass =
  'pt-2 pb-2.5 text-body-xs font-medium text-fg-3 outline-none transition-colors duration-(--duration-micro) ease-hover hover:text-fg-1 focus-visible:rounded-xs focus-visible:outline-2 focus-visible:outline-ring data-active:font-semibold data-active:text-fg-1';

/** Settings of the selected step: header, tabs «Параметры · Данные · Запуски», fields. Without `params` — a plain body. */
export function CanvasInspector({
  title,
  subtitle,
  icon,
  onClose,
  variant = 'panel',
  errors = 0,
  params,
  data,
  runs,
  runCount,
  tab,
  defaultTab = 'params',
  onTabChange,
  className,
  children,
  ...props
}: CanvasInspectorProps) {
  const titleId = useId();
  const [current, setCurrent] = useControllable<InspectorTab>(tab, defaultTab, onTabChange);
  const banner =
    errors > 0 ? (
      <p role="alert" className="flex items-center gap-2 rounded-[10px] bg-danger-soft px-3 py-2.5 text-body-xs font-medium text-danger-soft-fg">
        <CircleAlert aria-hidden className="size-4 shrink-0 fill-danger stroke-danger-fg stroke-[2.25]" />
        {`${errors} ${pluralRu(errors, ['ошибка мешает', 'ошибки мешают', 'ошибок мешают'])} публиковать`}
      </p>
    ) : null;
  const body = (content: ReactNode) => (
    <div className="flex flex-col gap-4 p-4">
      {banner}
      {content}
    </div>
  );

  return (
    <section data-slot="canvas-inspector" data-variant={variant} aria-labelledby={titleId} className={cn('flex flex-col', variants[variant], className)} {...props}>
      <header className={cn('flex items-center gap-2.5 pt-3.5 pr-3 pb-3 pl-4', params === undefined && 'border-b border-separator')}>
        {icon}
        <div className="flex min-w-0 flex-1 flex-col">
          <h2 id={titleId} className="truncate text-body-sm font-semibold text-fg-1">
            {title}
          </h2>
          {subtitle ? <p className="truncate text-caption text-fg-3">{subtitle}</p> : null}
        </div>
        {onClose ? (
          <button
            type="button"
            aria-label="Закрыть инспектор"
            onClick={onClose}
            className="kv-pressable grid size-7 shrink-0 place-items-center rounded-sm text-fg-3 [--kv-press-scale:var(--scale-press-icon)] hover:bg-fill-2 hover:text-fg-1 active:bg-fill-3"
          >
            <X aria-hidden className="size-4 stroke-[1.75]" />
          </button>
        ) : null}
      </header>
      {params === undefined ? (
        body(children)
      ) : (
        <BaseTabs.Root value={current} onValueChange={(value: InspectorTab) => setCurrent(value)} className="flex flex-col">
          <BaseTabs.List className="relative flex gap-4 border-b border-separator px-4">
            <BaseTabs.Tab value="params" className={tabClass}>
              Параметры
            </BaseTabs.Tab>
            <BaseTabs.Tab value="data" className={tabClass}>
              Данные
            </BaseTabs.Tab>
            <BaseTabs.Tab value="runs" className={tabClass}>
              {runCount === 0 ? 'Запусков нет' : runCount === undefined ? 'Запуски' : `Запуски ${runCount}`}
            </BaseTabs.Tab>
            <BaseTabs.Indicator className="kv-slide absolute -bottom-px left-0 h-0.5 w-(--active-tab-width) translate-x-(--active-tab-left) bg-fg-1" />
          </BaseTabs.List>
          <BaseTabs.Panel value="params" className="outline-none">
            {body(params)}
          </BaseTabs.Panel>
          <BaseTabs.Panel value="data" className="outline-none">
            {body(data ?? <p className="text-body-xs text-fg-3">Данные появятся после первого запуска.</p>)}
          </BaseTabs.Panel>
          <BaseTabs.Panel value="runs" className="outline-none">
            {body(runs ?? <p className="text-body-xs text-fg-3">Шаг ещё не запускался.</p>)}
          </BaseTabs.Panel>
        </BaseTabs.Root>
      )}
    </section>
  );
}

export interface InspectorIconProps extends Omit<ComponentProps<'span'>, 'color'> {
  /** Colour of the step kind: `var(--color-chart-4)` for logic, `var(--color-brand-telegram)`. */
  color: string;
  /** Brand tile: solid colour with a white glyph (Telegram); otherwise a 14 % tint. */
  solid?: boolean;
}

/** 28 tile of the step kind in the inspector header. */
export function InspectorIcon({ color, solid = false, className, style, ...props }: InspectorIconProps) {
  const tone: CSSProperties = solid ? { backgroundColor: color, color: 'var(--color-surface-1)' } : { backgroundColor: `color-mix(in oklab, ${color} 14%, transparent)`, color };
  return (
    <span
      aria-hidden
      data-slot="inspector-icon"
      className={cn('grid size-7 shrink-0 place-items-center rounded-sm [&_svg]:size-3.5 [&_svg]:stroke-2', className)}
      style={{ ...tone, ...style }}
      {...props}
    />
  );
}

/* ---------- Groups and lists ---------- */

export interface InspectorGroupProps extends Omit<ComponentProps<'div'>, 'title'> {
  /** «Выходы», «Правила». */
  label: ReactNode;
  /** Accent text action on the right, after a «+»: «Поле», «Правило», «Класс». */
  actionLabel?: string;
  onAction?: () => void;
}

/** A labelled block of the inspector for lists: outputs, rules, branches, fields. Single controls go in Field. */
export function InspectorGroup({ label, actionLabel, onAction, className, children, ...props }: InspectorGroupProps) {
  return (
    <div data-slot="inspector-group" className={cn('flex flex-col gap-1.5', className)} {...props}>
      <div className="flex items-center justify-between gap-2">
        <span className="text-caption font-medium text-fg-2">{label}</span>
        {actionLabel && onAction ? (
          <button type="button" onClick={onAction} className="rounded-xs text-caption font-medium text-accent hover:text-accent-hover active:text-accent-pressed">
            + {actionLabel}
          </button>
        ) : null}
      </div>
      {children}
    </div>
  );
}

/** Bordered list r10 with separators: rows of rules, branches, mapped fields. */
export function InspectorList({ className, ...props }: ComponentProps<'ul'>) {
  return <ul data-slot="inspector-list" className={cn('flex flex-col divide-y divide-separator rounded-[10px] shadow-[inset_0_0_0_1px_var(--color-border)]', className)} {...props} />;
}

export function InspectorListItem({ className, ...props }: ComponentProps<'li'>) {
  return <li data-slot="inspector-list-item" className={cn('flex min-h-control-md items-center gap-2 px-3 py-1.5 text-body-xs text-fg-1', className)} {...props} />;
}

const roundTypes: ReadonlySet<CanvasPortType> = new Set(['number', 'boolean']);
const hollowTypes: ReadonlySet<CanvasPortType> = new Set(['object', 'list', 'tool', 'memory', 'knowledge']);

/** Port mark of a type: numbers round, the rest square; structures hollow. */
export function PortMark({ type, className }: { type: CanvasPortType; className?: string }) {
  return (
    <span
      aria-hidden
      data-slot="port-mark"
      data-type={type}
      className={cn(
        'size-2.5 shrink-0 border-2 border-fg-4',
        roundTypes.has(type) ? 'rounded-full' : 'rounded-[3px]',
        hollowTypes.has(type) ? 'bg-surface-1' : 'bg-fg-4 shadow-[inset_0_0_0_2px_var(--color-surface-1)]',
        className,
      )}
    />
  );
}

export interface InspectorOutput {
  /** Name the next steps use: `budget`, `сообщение.текст`. */
  name: string;
  type: CanvasPortType;
  /** Value from the last run: «120 000». */
  value?: ReactNode;
}

export interface InspectorOutputsProps extends ComponentProps<'ul'> {
  outputs: readonly InspectorOutput[];
}

/** Outputs of the step: port mark, mono name, type and the value of the last run. */
export function InspectorOutputs({ outputs, className, ...props }: InspectorOutputsProps) {
  return (
    <InspectorList className={className} {...props}>
      {outputs.map((output) => (
        <InspectorListItem key={output.name} className="h-control-md py-0">
          <PortMark type={output.type} />
          <span className="min-w-0 flex-1 truncate font-mono text-caption font-medium">{output.name}</span>
          <span className="w-14 shrink-0 text-right text-caption text-fg-3">{portTypeName(output.type)}</span>
          {output.value !== undefined ? <span className="w-20 shrink-0 truncate text-right text-caption font-medium tabular-nums">{output.value}</span> : null}
        </InspectorListItem>
      ))}
    </InspectorList>
  );
}

/** A variable of an earlier step: mono `{{заявка.task}}` on accent-soft. */
export function VariableChip({ path, className, ...props }: Omit<ComponentProps<'span'>, 'children'> & { path: string }) {
  return (
    <span
      data-slot="variable-chip"
      className={cn('inline-flex h-[22px] max-w-full items-center truncate rounded-xs bg-accent-soft px-1.5 font-mono text-overline font-medium text-accent-soft-fg', className)}
      {...props}
    >{`{{${path}}}`}</span>
  );
}

/** Surface-2 note under the fields: «Прошлый запуск — 3 мин назад» and what happened. */
export function InspectorNote({ title, className, children, ...props }: Omit<ComponentProps<'div'>, 'title'> & { title: ReactNode }) {
  return (
    <div data-slot="inspector-note" className={cn('flex flex-col gap-1 rounded-[10px] bg-surface-2 p-3', className)} {...props}>
      <p className="text-body-xs font-medium text-fg-1">{title}</p>
      {children ? <p className="text-caption text-fg-3">{children}</p> : null}
    </div>
  );
}

/* ---------- Instruction with variables ---------- */

export type InstructionPart = { type: 'text'; value: string } | { type: 'variable'; value: string; path: string };

/** Splits an instruction into text and `{{path}}` variables; an unclosed `{{` stays text. */
export function splitVariables(text: string): InstructionPart[] {
  const parts: InstructionPart[] = [];
  let last = 0;
  for (const match of text.matchAll(/\{\{\s*([^{}]+?)\s*\}\}/g)) {
    if (match.index > last) parts.push({ type: 'text', value: text.slice(last, match.index) });
    parts.push({ type: 'variable', value: match[0], path: match[1] ?? '' });
    last = match.index + match[0].length;
  }
  if (last < text.length) parts.push({ type: 'text', value: text.slice(last) });
  return parts;
}

export interface InstructionFieldProps extends Omit<ComponentProps<'textarea'>, 'value' | 'defaultValue' | 'onChange'> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Variables of earlier steps offered under the text; a click inserts one at the caret. */
  variables?: readonly string[];
  invalid?: boolean;
}

// The mirror and the textarea must wrap identically: same font, size, padding and break rules.
const textMetrics = 'px-3 py-2.5 font-sans text-[13px]/[19px] whitespace-pre-wrap break-words';

/** Instruction for the agent: plain text where `{{variables}}` light up as you type them. */
export function InstructionField({ value: valueProp, defaultValue = '', onValueChange, variables = [], invalid, className, ...props }: InstructionFieldProps) {
  const [value, setValue] = useControllable(valueProp, defaultValue, onValueChange);
  const field = useRef<HTMLTextAreaElement>(null);
  const hintId = useId();

  const insert = (path: string) => {
    const element = field.current;
    const token = `{{${path}}}`;
    const start = element?.selectionStart ?? value.length;
    const end = element?.selectionEnd ?? value.length;
    setValue(value.slice(0, start) + token + value.slice(end));
    requestAnimationFrame(() => {
      element?.focus();
      element?.setSelectionRange(start + token.length, start + token.length);
    });
  };

  return (
    <div
      data-slot="instruction-field"
      data-invalid={invalid || undefined}
      className={cn(
        'flex flex-col rounded-[10px] bg-field shadow-[inset_0_0_0_1px_var(--color-border)] transition-shadow duration-(--duration-fast) ease-hover focus-within:shadow-[inset_0_0_0_1.5px_var(--color-ring)] data-invalid:shadow-[inset_0_0_0_1.5px_var(--color-danger)]',
        className,
      )}
    >
      <div className="relative">
        <div aria-hidden className={cn(textMetrics, 'min-h-[76px] text-fg-1')}>
          {splitVariables(value).map((part, index) =>
            part.type === 'variable' ? (
              <mark key={index} data-slot="instruction-variable" className="rounded-[3px] bg-accent-soft text-accent-soft-fg">
                {part.value}
              </mark>
            ) : (
              <span key={index}>{part.value}</span>
            ),
          )}
          {/* keeps a trailing newline one line tall */}
          {'​'}
        </div>
        <textarea
          ref={field}
          value={value}
          aria-describedby={hintId}
          aria-invalid={invalid || undefined}
          onChange={(event) => setValue(event.target.value)}
          className={cn(textMetrics, 'absolute inset-0 resize-none overflow-hidden bg-transparent text-transparent caret-fg-1 outline-none placeholder:text-fg-3')}
          {...props}
        />
      </div>
      <div className="flex flex-col items-start gap-1 px-3 pb-2.5">
        <span id={hintId} className="text-caption text-fg-3">
          Переменные из прошлых шагов — набрать {'{{'}
        </span>
        {variables.length ? (
          <span className="flex flex-wrap gap-1">
            {variables.map((path) => (
              <button
                key={path}
                type="button"
                aria-label={`Вставить {{${path}}}`}
                onClick={() => insert(path)}
                className="rounded-xs font-mono text-overline font-medium text-accent-soft-fg hover:bg-accent-soft"
              >{`{{${path}}}`}</button>
            ))}
          </span>
        ) : null}
      </div>
    </div>
  );
}

/* ---------- Nothing selected ---------- */

export interface InspectorEmptyProps extends ComponentProps<'div'> {
  steps: number;
  edges: number;
  /** Warnings of the check: a warning badge, 0 hides the row. */
  warnings?: number;
}

/** Inspector with no step selected: a hint, the size of the graph and, as children, the version note. */
export function InspectorEmpty({ steps, edges, warnings = 0, className, children, ...props }: InspectorEmptyProps) {
  return (
    <div data-slot="inspector-empty" className={cn('flex flex-col gap-4', className)} {...props}>
      <div className="flex flex-col items-center gap-1.5 px-2 pt-5 pb-3 text-center">
        <span aria-hidden className="mb-1.5 grid size-10 place-items-center rounded-md bg-fill-2 text-fg-2">
          <MousePointer2 className="size-4.5 stroke-[1.75]" />
        </span>
        <p className="text-body-sm font-semibold text-fg-1">Выберите шаг</p>
        <p className="text-body-xs text-fg-2">Его настройки появятся здесь</p>
        <p className="flex items-center gap-1.5 pt-1 text-caption text-fg-3">
          Добавить шаг — <Kbd>Tab</Kbd>
        </p>
      </div>
      <InspectorGroup label="Граф">
        <InspectorList aria-label="Граф">
          <InspectorListItem className="justify-between">
            Шаги<span className="font-medium tabular-nums">{steps}</span>
          </InspectorListItem>
          <InspectorListItem className="justify-between">
            Связи<span className="font-medium tabular-nums">{edges}</span>
          </InspectorListItem>
          {warnings > 0 ? (
            <InspectorListItem className="justify-between">
              Предупреждения
              <Badge tone="warning">{warnings}</Badge>
            </InspectorListItem>
          ) : null}
        </InspectorList>
      </InspectorGroup>
      {children}
    </div>
  );
}

import type { CanvasEdge, CanvasGraph, CanvasNode, CanvasPort, CanvasPortType } from './canvas-types';

/* ---------- Graph check ---------- */

export type CanvasProblemSeverity = 'error' | 'warning';

export type CanvasProblemKind = 'no-trigger' | 'cycle' | 'required-input' | 'unreachable' | 'open-branch' | 'broken-edge' | 'type-mismatch';

export interface CanvasProblem {
  /** Stable between runs of the same graph: kind plus the ids involved. */
  id: string;
  kind: CanvasProblemKind;
  /** error blocks publishing, warning does not. */
  severity: CanvasProblemSeverity;
  /** «Цикл без выхода». */
  title: string;
  /** What is wrong and how to fix it, with step names. */
  description: string;
  /** Steps to show: the first one gets the camera. */
  nodeIds: readonly string[];
  edgeId?: string;
  portId?: string;
}

export interface CheckGraphOptions<TData> {
  /** Step name in the messages; default — the node id. */
  label?: (node: CanvasNode<TData>) => string;
  /** Inputs that must be connected; default — ports marked `required`, the same ones the canvas draws in danger. */
  isRequired?: (node: CanvasNode<TData>, port: CanvasPort) => boolean;
}

/** Notes and groups are not steps: they never run and need no connections. */
const isStep = (node: CanvasNode<unknown>) => node.kind !== 'note' && node.kind !== 'group';

const typeNames: Record<CanvasPortType, string> = {
  flow: 'поток',
  text: 'текст',
  number: 'число',
  date: 'дата',
  boolean: 'да/нет',
  object: 'объект',
  list: 'список',
  tool: 'инструмент',
  memory: 'память',
  knowledge: 'знания',
};

/** Russian name of a port type: «текст», «число». */
export function portTypeName(type: CanvasPortType): string {
  return typeNames[type];
}

const capitalize = (text: string) => text.charAt(0).toUpperCase() + text.slice(1);

const plurals = new Intl.PluralRules('ru');

/** Russian noun for a count: `pluralRu(2, ['ошибка', 'ошибки', 'ошибок'])` → «ошибки». */
export function pluralRu(count: number, [one, few, many]: readonly [one: string, few: string, many: string]): string {
  const rule = plurals.select(count);
  return rule === 'one' ? one : rule === 'few' ? few : many;
}

// Anything becomes text without loss, so number, date and yes/no flow into text silently.
const intoText: ReadonlySet<CanvasPortType> = new Set(['number', 'date', 'boolean']);

function compatibility(from: CanvasPortType | undefined, to: CanvasPortType | undefined): 'ok' | 'convert' | 'wrong' {
  if (!from || !to || from === to) return 'ok';
  if (from === 'flow' || to === 'flow') return 'wrong';
  if (to === 'text' && intoText.has(from)) return 'ok';
  return 'convert';
}

/** Strongly connected components (Tarjan), each in discovery order. */
function components(ids: readonly string[], next: ReadonlyMap<string, readonly string[]>): string[][] {
  const index = new Map<string, number>();
  const low = new Map<string, number>();
  const stack: string[] = [];
  const onStack = new Set<string>();
  const result: string[][] = [];
  let counter = 0;

  const visit = (id: string) => {
    index.set(id, counter);
    low.set(id, counter);
    counter += 1;
    stack.push(id);
    onStack.add(id);
    for (const target of next.get(id) ?? []) {
      if (!index.has(target)) {
        visit(target);
        low.set(id, Math.min(low.get(id) ?? 0, low.get(target) ?? 0));
      } else if (onStack.has(target)) {
        low.set(id, Math.min(low.get(id) ?? 0, index.get(target) ?? 0));
      }
    }
    if (low.get(id) !== index.get(id)) return;
    const component: string[] = [];
    let member: string | undefined;
    do {
      member = stack.pop();
      if (member === undefined) break;
      onStack.delete(member);
      component.push(member);
    } while (member !== id);
    result.push(component);
  };

  for (const id of ids) if (!index.has(id)) visit(id);
  return result;
}

/** One loop through the component from its first step, to name it «А → Б → А». */
function loopPath(start: string, members: ReadonlySet<string>, next: ReadonlyMap<string, readonly string[]>): string[] {
  const path: string[] = [];
  const seen = new Set<string>();
  const walk = (id: string): boolean => {
    path.push(id);
    seen.add(id);
    for (const target of next.get(id) ?? []) {
      if (target === start) return true;
      if (members.has(target) && !seen.has(target) && walk(target)) return true;
    }
    path.pop();
    return false;
  };
  walk(start);
  return path;
}

/**
 * Finds what breaks a run before it starts: cycles with no way out, empty required inputs, steps the trigger never
 * reaches, branches left open after a fork, edges to missing ports and data of the wrong type. Errors come first.
 */
export function checkGraph<TData>(graph: CanvasGraph<TData>, options: CheckGraphOptions<TData> = {}): CanvasProblem[] {
  const { label = (node: CanvasNode<TData>) => node.id, isRequired = (_node: CanvasNode<TData>, port: CanvasPort) => port.required === true } = options;
  const problems: CanvasProblem[] = [];
  const steps = graph.nodes.filter((node) => isStep(node) && !node.disabled);
  const byId = new Map(graph.nodes.map((node) => [node.id, node]));
  const name = (id: string) => {
    const node = byId.get(id);
    return node ? label(node) : id;
  };
  const portOf = (node: CanvasNode<TData> | undefined, id: string) => node?.ports.find((port) => port.id === id);

  // Edges that point at real ports in the right direction; the rest are broken.
  const edges: CanvasEdge[] = [];
  for (const edge of graph.edges) {
    const source = portOf(byId.get(edge.source), edge.sourcePort);
    const target = portOf(byId.get(edge.target), edge.targetPort);
    if (source?.direction === 'out' && target?.direction === 'in') {
      edges.push(edge);
      continue;
    }
    problems.push({
      id: `broken-edge:${edge.id}`,
      kind: 'broken-edge',
      severity: 'error',
      title: 'Связь никуда не ведёт',
      description: `Связь «${name(edge.source)}» → «${name(edge.target)}» держится за порт, которого нет. Удалите её и протяните заново.`,
      nodeIds: [edge.source, edge.target].filter((id) => byId.has(id)),
      edgeId: edge.id,
    });
  }

  const next = new Map<string, string[]>();
  for (const edge of edges) next.set(edge.source, [...(next.get(edge.source) ?? []), edge.target]);

  if (steps.length && !steps.some((node) => node.kind === 'trigger')) {
    problems.push({
      id: 'no-trigger',
      kind: 'no-trigger',
      severity: 'error',
      title: 'Нет триггера',
      description: 'Граф ничто не запускает. Добавьте триггер: сообщение, расписание или вебхук.',
      nodeIds: [],
    });
  }

  for (const component of components(
    steps.map((node) => node.id),
    next,
  )) {
    const members = new Set(component);
    const [only] = component;
    if (component.length === 1 && only !== undefined && !(next.get(only) ?? []).includes(only)) continue;
    const exits = component.some((id) => {
      const kind = byId.get(id)?.kind;
      return (kind === 'condition' || kind === 'loop') && (next.get(id) ?? []).some((target) => !members.has(target));
    });
    if (exits) continue;
    const first = steps.find((node) => members.has(node.id))?.id ?? component[0] ?? '';
    const path = loopPath(first, members, next);
    const ordered = [...path, ...component.filter((id) => !path.includes(id))];
    problems.push({
      id: `cycle:${[...component].sort().join(',')}`,
      kind: 'cycle',
      severity: 'error',
      title: 'Цикл без выхода',
      description: `${[...path, first].map(name).join(' → ')}. Добавьте условие, которое выводит из цикла, например «не больше 3 раз».`,
      nodeIds: ordered,
    });
  }

  for (const node of steps) {
    for (const port of node.ports) {
      if (port.direction !== 'in' || !isRequired(node, port)) continue;
      if (edges.some((edge) => edge.target === node.id && edge.targetPort === port.id)) continue;
      problems.push({
        id: `required-input:${node.id}:${port.id}`,
        kind: 'required-input',
        severity: 'error',
        title: 'Пустой обязательный вход',
        description: `«${label(node)}» ждёт «${port.label ?? port.id}», но к нему ничего не подключено.`,
        nodeIds: [node.id],
        portId: port.id,
      });
    }
  }

  const triggers = steps.filter((node) => node.kind === 'trigger');
  if (triggers.length) {
    const reached = new Set<string>();
    const queue = triggers.map((node) => node.id);
    for (let id = queue.shift(); id !== undefined; id = queue.shift()) {
      if (reached.has(id)) continue;
      reached.add(id);
      queue.push(...(next.get(id) ?? []));
    }
    for (const node of steps) {
      if (reached.has(node.id)) continue;
      problems.push({
        id: `unreachable:${node.id}`,
        kind: 'unreachable',
        severity: 'warning',
        title: 'Шаг не запустится',
        description: `До «${label(node)}» не доходит ни одна связь от триггера. Подключите его или удалите.`,
        nodeIds: [node.id],
      });
    }
  }

  for (const node of steps) {
    const outs = node.ports.filter((port) => port.direction === 'out' && (port.type ?? 'flow') === 'flow');
    if (outs.length < 2) continue;
    const used = outs.filter((port) => edges.some((edge) => edge.source === node.id && edge.sourcePort === port.id));
    if (!used.length) continue;
    for (const port of outs) {
      if (used.includes(port)) continue;
      problems.push({
        id: `open-branch:${node.id}:${port.id}`,
        kind: 'open-branch',
        severity: 'warning',
        title: 'Ветка обрывается',
        description: `У «${label(node)}» ветка «${port.label ?? port.id}» никуда не ведёт — этот случай останется без действия.`,
        nodeIds: [node.id],
        portId: port.id,
      });
    }
  }

  for (const edge of edges) {
    const from = portOf(byId.get(edge.source), edge.sourcePort)?.type;
    const to = portOf(byId.get(edge.target), edge.targetPort);
    const verdict = compatibility(from, to?.type);
    if (verdict === 'ok' || !from || !to?.type) continue;
    const wrong = verdict === 'wrong';
    problems.push({
      id: `type-mismatch:${edge.id}`,
      kind: 'type-mismatch',
      severity: wrong ? 'error' : 'warning',
      title: wrong ? 'Данные вместо шага' : `${capitalize(typeNames[from])} идёт в ${typeNames[to.type]}`,
      description: wrong
        ? `Связь «${name(edge.source)}» → «${name(edge.target)}» соединяет порядок шагов с данными. Подключите её к порту того же вида.`
        : `«${to.label ?? to.id}» получает ${typeNames[from]} — вставить конвертер «${typeNames[from]} → ${typeNames[to.type]}»?`,
      nodeIds: [edge.target, edge.source],
      edgeId: edge.id,
      portId: to.id,
    });
  }

  // Array#sort is stable: within a severity the order of discovery stays.
  return problems.sort((a, b) => (a.severity === b.severity ? 0 : a.severity === 'error' ? -1 : 1));
}

/* ---------- Version diff ---------- */

export interface CanvasGraphDiff {
  nodes: { added: string[]; changed: string[]; removed: string[]; unchanged: string[] };
  edges: { added: string[]; removed: string[] };
}

export interface DiffGraphsOptions<TData> {
  /** Whether a step stayed the same; default compares kind, ports, parent, flags and data deeply. */
  same?: (before: CanvasNode<TData>, after: CanvasNode<TData>) => boolean;
}

function deepEqual(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true;
  if (typeof a !== 'object' || typeof b !== 'object' || a === null || b === null) return false;
  if (a instanceof Date || b instanceof Date) return a instanceof Date && b instanceof Date && a.getTime() === b.getTime();
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const keysA = Object.keys(a).filter((key) => (a as Record<string, unknown>)[key] !== undefined);
  const keysB = Object.keys(b).filter((key) => (b as Record<string, unknown>)[key] !== undefined);
  return keysA.length === keysB.length && keysA.every((key) => deepEqual((a as Record<string, unknown>)[key], (b as Record<string, unknown>)[key]));
}

// Position, size, selection and run status are view state: moving a step is not an edit of the automation.
const meaning = <TData>({ kind, ports, parentId, disabled, collapsed, data }: CanvasNode<TData>) => ({ kind, ports, parentId, disabled, collapsed, data });

/** What changed between two versions: steps added, changed, removed; edges added and removed. */
export function diffGraphs<TData>(before: CanvasGraph<TData>, after: CanvasGraph<TData>, options: DiffGraphsOptions<TData> = {}): CanvasGraphDiff {
  const { same = (a: CanvasNode<TData>, b: CanvasNode<TData>) => deepEqual(meaning(a), meaning(b)) } = options;
  const old = new Map(before.nodes.map((node) => [node.id, node]));
  const fresh = new Set(after.nodes.map((node) => node.id));
  const diff: CanvasGraphDiff = { nodes: { added: [], changed: [], removed: [], unchanged: [] }, edges: { added: [], removed: [] } };
  for (const node of after.nodes) {
    const previous = old.get(node.id);
    if (!previous) diff.nodes.added.push(node.id);
    else if (same(previous, node)) diff.nodes.unchanged.push(node.id);
    else diff.nodes.changed.push(node.id);
  }
  diff.nodes.removed = before.nodes.filter((node) => !fresh.has(node.id)).map((node) => node.id);
  const key = (edge: CanvasEdge) => `${edge.source}\u0000${edge.sourcePort}\u0000${edge.target}\u0000${edge.targetPort}`;
  const oldEdges = new Set(before.edges.map(key));
  const newEdges = new Set(after.edges.map(key));
  diff.edges.added = after.edges.filter((edge) => !oldEdges.has(key(edge))).map((edge) => edge.id);
  diff.edges.removed = before.edges.filter((edge) => !newEdges.has(key(edge))).map((edge) => edge.id);
  return diff;
}

// Graph model shared by the canvas engine, node cards, editor chrome and graph checks.

export type CanvasNodeKind = 'trigger' | 'action' | 'condition' | 'loop' | 'wait' | 'agent' | 'data' | 'group' | 'note';

/** Run state of a step or an edge: waiting → running → done | error; warning is a config problem before any run. */
export type CanvasRunStatus = 'idle' | 'waiting' | 'running' | 'done' | 'error' | 'warning' | 'skipped';

export type CanvasPortSide = 'top' | 'right' | 'bottom' | 'left';

export type CanvasPortDirection = 'in' | 'out';

/** flow carries the order of steps; the rest carry data and are coloured by type. */
export type CanvasPortType = 'flow' | 'text' | 'number' | 'date' | 'boolean' | 'object' | 'list' | 'tool' | 'memory' | 'knowledge';

export type CanvasEdgePath = 'bezier' | 'smoothstep' | 'step' | 'straight' | 'orthogonal';

export interface CanvasPoint {
  x: number;
  y: number;
}

/** x/y is the screen offset of the graph origin, zoom is the scale. */
export interface CanvasViewport {
  x: number;
  y: number;
  zoom: number;
}

export interface CanvasPort {
  id: string;
  side: CanvasPortSide;
  direction: CanvasPortDirection;
  type?: CanvasPortType;
  label?: string;
  /** More than one edge may attach; outputs default to true, inputs to false. */
  multiple?: boolean;
  /** Centre along the side in px from the node's top (left/right) or left edge (top/bottom); default: spread evenly. */
  offset?: number;
  /** An input the step cannot run without: drawn in danger while nothing is connected. */
  required?: boolean;
}

export interface CanvasNode<TData = unknown> {
  id: string;
  kind: CanvasNodeKind;
  /** Top-left corner in graph coordinates; relative to the parent group when parentId is set. */
  position: CanvasPoint;
  width?: number;
  height?: number;
  ports: readonly CanvasPort[];
  parentId?: string;
  selected?: boolean;
  collapsed?: boolean;
  disabled?: boolean;
  status?: CanvasRunStatus;
  /** Size handles when selected; default: groups and notes (steps keep a fixed width). */
  resizable?: boolean;
  data: TData;
}

export interface CanvasEdge {
  id: string;
  source: string;
  sourcePort: string;
  target: string;
  targetPort: string;
  path?: CanvasEdgePath;
  label?: string;
  status?: CanvasRunStatus;
  selected?: boolean;
}

export interface CanvasGraph<TData = unknown> {
  nodes: readonly CanvasNode<TData>[];
  edges: readonly CanvasEdge[];
}

/** An edge before it has an id: what a drag from port to port proposes. */
export interface CanvasConnection {
  source: string;
  sourcePort: string;
  target: string;
  targetPort: string;
}

/** select is not an edit: history replaces the present instead of adding a step. add and update come from the editor around the canvas. */
export type CanvasChangeType = 'select' | 'move' | 'resize' | 'connect' | 'reconnect' | 'delete' | 'paste' | 'layout' | 'label' | 'add' | 'update';

/** Why the graph changed; history uses it to merge and skip steps. */
export interface CanvasChange {
  type: CanvasChangeType;
  nodeIds?: readonly string[];
  edgeIds?: readonly string[];
  /** Changes with the same key in a row within a second are one history step (arrow-key nudges). */
  mergeKey?: string;
}
